private void LoadTopCategories()
{
    if (!wrapper.Visible) return;

    string cacheKey = "TOP5_CATEGORY_NEWS_" + ResManager.CurrentLanguageID;
    DataTable dt = Cache[cacheKey] as DataTable;

    if (dt == null)
    {
        var info = new INFO_Information();
        dt = info.GetDataTable(
            "INFO_Category_Top5_ByNewsCount",
            "@LanguageID", ResManager.CurrentLanguageID,
            "@Top", 5
        );

        if (dt != null && dt.Rows.Count > 0)
        {
            Cache.Insert(
                cacheKey,
                dt,
                null,
                DateTime.Now.AddMinutes(10),
                Cache.NoSlidingExpiration
            );
        }
    }

    if (dt == null || dt.Rows.Count == 0)
    {
        pnlCategories.Visible = false;
        return;
    }

    if (!dt.Columns.Contains("IsActive"))
        dt.Columns.Add("IsActive", typeof(bool));

    foreach (DataRow r in dt.Rows)
    {
        int cid = 0;
        int.TryParse(r["CategoryID"].ToString(), out cid);
        r["IsActive"] = (cid == currentCategoryID);

        if (dt.Columns.Contains("CategoryLink"))
        {
            string cl = (r["CategoryLink"] ?? "").ToString();
            if (!string.IsNullOrEmpty(cl) && !cl.StartsWith("/"))
                r["CategoryLink"] = "/" + cl;
        }
    }

    rptCategories.DataSource = dt;
    rptCategories.DataBind();
    pnlCategories.Visible = true;
}

